          ],
          "id": ""
        }
      }
    },
    {
      "id": "cell-20",
      "source": "<p>Let’s compute the hidden states for all DNA sequences:</p>\n",
      "cell_type": "markdown",
      "metadata": {
        "editable": false,
        "collapsed": false
      }
    },
    {
      "id": "cell-21",
      "source": [
        "tokenized_dna = tokenizer(\n",
