        "exon_mut_seqs = exon_mut_seqs[0:kseq]\n",
        "intron_wt_seqs = intron_wt_seqs[0:kseq]\n",
        "intron_mut_seqs = intron_mut_seqs[0:kseq]"
      ],
      "cell_type": "code",
