        "ax.set_ylabel(\"R2\")\n",
        "ax.set_ylim(-0.1, 1.1)\n",
        "ax.legend()\n",
        "\n",
        "fig.suptitle(f\"best alpha : {10**bestLogAlpha:.2f} - cross-validated R2 : {bestR2_valid:.2f}\")"
      ],
