        "fig,ax = plt.subplots(1, 2, figsize=(14,5))\n",
        "\n",
        "sns.histplot(x=X1, hue=y, ax=ax[0])\n",
        "\n",
        "ax[1].scatter(X1_norm, y, c=y)\n",
        "\n",
        "for alpha in [0.01, 0.1, 1, 10]:\n",
        "    # this implementation does not take alpham but rather C = 1/alpha\n",
