        "    n_samples=250,\n",
        "    centers=blob_centers,\n",
        "    cluster_std=blob_stds,\n",
        "    random_state=42\n",
        ")\n",
        "\n",
        "plt.scatter(X_3[:, 0], X_3[:, 1], c=y_3, cmap=plt.cm.coolwarm, edgecolors=\"k\")"
      ],
