      "cell_type": "markdown",
      "metadata": {
        "editable": false,
        "collapsed": false
      }
    },
    {
      "id": "cell-27",
      "source": [
        "print(dset.where(dset['pm2p5_conc'] > 25))"
      ],
      "cell_type": "code",
      "execution_count": null,
      "outputs": [],
      "metadata": {
        "attributes": {
          "classes": [
            "We will be using data from [Copernicus Atmosphere Monitoring Service](https://ads.atmosphere.copernicus.eu/)"
          ],
          "id": ""
        }
      }
    },
    {
      "id": "cell-28",
      "source": "<blockquote class=\"comment\" style=\"border: 2px solid #ffecc1; margin: 1em 0.2em\">\n<div class=\"box-title comment-title\" id=\"comment-what-happened\"><i class=\"far fa-comment-dots\" aria-hidden=\"true\" ></i> Comment: What happened?</div>\n<p>Each element of the dataset where the criteria within the <code style=\"color: inherit\">where</code> statement is not met, e.g. when PM2.5 &lt;= 25, will be set to <code style=\"color: inherit\">nan</code>.\nYou may not see any changes when printing the dataset but if you look carefuly at <code style=\"color: inherit\">pm2p5_conc</code> values, you will see many <code style=\"color: inherit\">nan</code>.</p>\n</blockquote>\n<p>Let’s plot one time to better see what happened:</p>\n",
      "cell_type": "markdown",
      "metadata": {
        "editable": false,
        "collapsed": false
      }
    },
    {
      "id": "cell-29",
      "source": [
        "######################\n",
        "# Plotting with mask #\n",
        "######################\n",
        "\n",
        "fig = plt.figure(1, figsize=[15,10])\n",
        "\n",
        "# We're using cartopy to project our data.\n",
        "# (see documentation on cartopy)\n",
        "ax = plt.subplot(1, 1, 1, projection=ccrs.Mercator())\n",
        "ax.coastlines(resolution='10m')\n",
        "\n",
        "# We need to project our data to the new projection and for this we use `transform`.\n",
        "# we set the original data projection in transform (here PlateCarree)\n",
        "dset.where(dset['pm2p5_conc'] > 25).isel(time=0)['pm2p5_conc'].plot(ax=ax,\n",
        "                                                                     transform=ccrs.PlateCarree(),\n",
        "                                                                     vmin = 0, vmax = 35,\n",
        "                                                                     cmap=cmc.roma_r)\n",
        "# One way to customize your title\n",
        "plt.title(\"Copernicus Atmosphere Monitoring Service PM2.5, 2 day forecasts\\n 24th December 2021 at 12:00 UTC\\n only values > 25\", fontsize=18)\n",
        "plt.savefig(\"CAMS-PM2_5-fc-20211224-25.png\")"
      ],
      "cell_type": "code",
      "execution_count": null,
