    {
      "id": "cell-58",
      "source": "<div>\n<style scoped=\"\">\n    .dataframe tbody tr th:only-of-type {\n        vertical-align: middle;\n    }\n\n    .dataframe tbody tr th {\n        vertical-align: top;\n    }\n\n    .dataframe thead th {\n        text-align: right;\n    }\n</style>\n<table border=\"1\" class=\"dataframe\">\n<thead>\n<tr style=\"text-align: right;\">\n<th></th>\n<th>aa</th>\n<th>frame</th>\n<th>phase</th>\n<th>start</th>\n<th>end</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<th>0</th>\n<td>RP</td>\n<td>0</td>\n<td>+</td>\n<td>0</td>\n<td>2</td>\n</tr>\n<tr>\n<th>1</th>\n<td>PKCV</td>\n<td>0</td>\n<td>+</td>\n<td>3</td>\n<td>7</td>\n</tr>\n<tr>\n<th>2</th>\n<td>MWLLGRISLRSVSVLVIGLLSAL</td>\n<td>0</td>\n<td>+</td>\n<td>8</td>\n<td>31</td>\n</tr>\n<tr>\n<th>3</th>\n<td>R</td>\n<td>0</td>\n<td>+</td>\n<td>32</td>\n<td>33</td>\n</tr>\n<tr>\n<th>4</th>\n<td>SLIIDKQQE</td>\n<td>0</td>\n<td>-</td>\n<td>0</td>\n<td>9</td>\n</tr>\n<tr>\n<th>5</th>\n<td>ELATDRRIKWWELRRLKASSRSL</td>\n<td>0</td>\n<td>-</td>\n<td>10</td>\n<td>33</td>\n</tr>\n<tr>\n<th>6</th>\n<td>DRSPSAFECGYLGGFHCGLSPYLLLVFFLHYDA</td>\n<td>1</td>\n<td>+</td>\n<td>0</td>\n<td>33</td>\n</tr>\n<tr>\n<th>7</th>\n<td>R</td>\n<td>1</td>\n<td>-</td>\n<td>0</td>\n<td>1</td>\n</tr>\n<tr>\n<th>8</th>\n<td></td>\n<td>1</td>\n<td>-</td>\n<td>2</td>\n<td>2</td>\n</tr>\n<tr>\n<th>9</th>\n<td>STNNRNKN</td>\n<td>1</td>\n<td>-</td>\n<td>3</td>\n<td>11</td>\n</tr>\n<tr>\n<th>10</th>\n<td>PQTGESNGGNYGD</td>\n<td>1</td>\n<td>-</td>\n<td>12</td>\n<td>25</td>\n</tr>\n<tr>\n<th>11</th>\n<td>KRVPVAC</td>\n<td>1</td>\n<td>-</td>\n<td>26</td>\n<td>33</td>\n</tr>\n<tr>\n<th>12</th>\n<td>TVAQVRLNVATWEDFIAVCLRTCYWSSFCIMT</td>\n<td>2</td>\n<td>+</td>\n<td>0</td>\n<td>32</td>\n</tr>\n<tr>\n<th>13</th>\n<td>ADNRQTTGIRTSHRQANQMVGTTEIESEFP</td>\n<td>2</td>\n<td>-</td>\n<td>0</td>\n<td>30</td>\n</tr>\n<tr>\n<th>14</th>\n<td>P</td>\n<td>2</td>\n<td>-</td>\n<td>31</td>\n<td>32</td>\n</tr>\n</tbody>\n</table>\n</div>\n<p>Now let’s plot it:</p>\n",
      "cell_type": "markdown",
      "metadata": {
        "editable": false,
        "collapsed": false
      }
    },
    {
      "id": "cell-59",
      "source": [
        "import altair as alt\n",
        "\n",
        "plus = alt.Chart(df[df['phase']=='+']).mark_rect().encode(\n",
        "    x = alt.X('start:Q'),\n",
        "    x2 = alt.X2('end:Q'),\n",
        "    y = alt.Y('frame:N'),\n",
        "    color='frame',\n",
        "    tooltip='aa:N'\n",
        "             ).properties(\n",
        "    width=600,\n",
        "    height=100)\n",
        "\n",
        "minus = alt.Chart(df[df['phase']=='-']).mark_rect().encode(\n",
        "    x = alt.X('start:Q',sort=alt.EncodingSortField('start:Q', order='descending')),\n",
        "    x2 = alt.X2('end:Q'),\n",
        "    y = alt.Y('frame:N'),\n",
        "    color='frame',\n",
        "    tooltip='aa:N'\n",
        "             ).properties(\n",
        "    width=600,\n",
        "    height=100)\n",
        "\n",
        "plus & minus"
      ],
      "cell_type": "code",
      "execution_count": null,
      "outputs": [],
      "metadata": {
        "attributes": {
          "classes": [
            ""
          ],
          "id": ""
        }
      }
    },
    {
      "id": "cell-60",
      "source": "<figure id=\"figure-1\" style=\"max-width: 90%;\"><div style=\"overflow-x: auto\"><object data=\"./images/orfs.svg\" type=\"image/svg+xml\" alt=\"ORFS. \">ORFS.</object></div><a target=\"_blank\" href=\"./images/orfs.svg\" rel=\"noopener noreferrer\"><small>Open image in new tab</small></a><br /><br /><figcaption><span class=\"figcaption-prefix\"><strong>Figure 1</strong>:</span> Translation on plus (top) and minus (bottom) strands.</figcaption></figure>\n",
      "cell_type": "markdown",
      "metadata": {
        "editable": false,
        "collapsed": false
      }
    },
    {
      "cell_type": "markdown",
