      "id": "cell-31",
      "source": [
        "start_codons = ['TTG', 'CTG', 'ATG']\n",
        "stop_codons = ['TAA', 'TAG', 'TGA']\n",
        "\n",
        "# And some convenience functions\n",
        "def is_start_codon(codon):\n",
        "    return codon in start_codons\n",
        "\n",
        "def is_stop_codon(codon):\n",
        "    return codon in stop_codons"
      ],
