    {
      "id": "cell-36",
      "source": "<p>Let’s try replacing it:</p>\n",
      "cell_type": "markdown",
      "metadata": {
        "editable": false,
        "collapsed": false
      }
    },
    {
      "id": "cell-37",
      "source": [
        "%%sql\n",
        "update olympics\n",
        "set city = 'Athens'\n",
        "where city = 'Athina';"
      ],
      "cell_type": "code",
      "execution_count": null,
      "outputs": [],
      "metadata": {
        "attributes": {
          "classes": [
