    },
    {
      "id": "cell-8",
      "source": "<p>X     [0, 1, 4, 9, 16, 25, 36, 49, 64, 81]\n    Xeven [0, 4, 16, 36, 64]\n    Xodd  [1, 9, 25, 49, 81]</p>\n<p><a href=\"#top\">back to the top</a></p>\n<h2 id=\"numpy-and-vectorized-operations\">numpy and vectorized operations</h2>\n",
