    {
      "id": "cell-73",
      "source": [
        "filtered_srt@meta.data<- mutate(filtered_srt@meta.data, celltype = case_when(\n",
        "  seurat_clusters %in% c(3) ~ \"Double negative (early T-cell)\",\n",
        "  seurat_clusters %in% c(1,2,5) ~ \" Double positive (middle T-cell)\",\n",
        "  seurat_clusters %in% c(0) ~ \"Double positive (late middle T-cell)\",\n",
        "  seurat_clusters %in% c(4) ~ \"Mature T-cell\"\n",
        "))"
      ],
      "cell_type": "code",
      "execution_count": null,
      "outputs": [],
      "metadata": {
        "attributes": {
          "classes": [
