          ],
          "id": ""
        }
      }
    },
    {
      "id": "cell-74",
      "source": "<p>Once we have labelled our clusters, we can visualize what our cell types actually look like:</p>\n",
      "cell_type": "markdown",
      "metadata": {
        "editable": false,
        "collapsed": false
      }
    },
    {
      "id": "cell-75",
      "source": [
        "DimPlot(object = filtered_srt, reduction = \"umap\", group.by = \"celltype\")"
